import{_ as a,C as s,c as r,o as i,a3 as t,G as n}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Lead scoring","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/assign-and-track/lead-scoring.md","filePath":"master/sales/crm/assign-and-track/lead-scoring.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/assign-and-track/lead-scoring.md"};function d(h,e,c,g,u,p){const o=s("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="lead-scoring" tabindex="-1">Lead scoring <a class="header-anchor" href="#lead-scoring" aria-label="Permalink to &quot;Lead scoring&quot;">​</a></h1><p>Lead scoring gives each open lead and opportunity a probability of winning. Aureus works it out from your own history of won and lost deals. You can then focus on the records with the best chance first.</p><blockquote><p><strong>In simple words:</strong> Aureus learns from your past wins and losses to guess which new records will win.</p></blockquote><p>The score is a percentage. It updates when a record changes and when you rebuild the scoring from the settings page.</p><div class="info custom-block"><p class="custom-block-title">About the example</p><p>The Sharma Textiles lead is in the first stage, has a valid email and phone, comes from the <strong>Newsletter</strong> source and carries the tag <strong>Software</strong>. You check what Aureus considers for it.</p></div><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><ol><li>Go to <code>CRM → Settings → Manage Lead Scoring</code>.</li><li>Choose the details Aureus should consider.</li><li>Set a start date if you want to ignore old records.</li><li>Click <strong>Save changes</strong>, or click <strong>Update Scoring Probabilities</strong>.</li></ol>',7)),n(o,{src:"/images1/crm/lead-scoring-settings.png",alt:"Manage Lead Scoring settings with criteria ticked and a start date entered"}),e[1]||(e[1]=t('<p>The page text reads: the probability of winning each open lead and opportunity is computed from your won and lost history. Stage and sales team are always used.</p><ul><li><strong><em>Also consider:</em></strong> Tick the details to add. The helper text reads <strong>Which details of a record the probability takes into account.</strong><ul><li><strong>Country:</strong> Where the record is located.</li><li><strong>State:</strong> The state of the record.</li><li><strong>Phone quality:</strong> Whether the phone number looks valid (at least 7 digits).</li><li><strong>Email quality:</strong> Whether the email address looks valid.</li><li><strong>Source:</strong> Where the record came from.</li><li><strong>Tags:</strong> The tags on the record.</li></ul></li><li><strong><em>Consider leads created as of the:</em></strong> A date, not later than today. Aureus learns only from records created on or after it. Leave it empty to use the whole history.</li></ul><p><strong>Example:</strong> Tick <strong>Country</strong>, <strong>Email quality</strong> and <strong>Source</strong>. Leave the date empty.</p><p>The stage and the sales team are always used. They have no tick box.</p><h2 id="update-the-scores" tabindex="-1">Update the scores <a class="header-anchor" href="#update-the-scores" aria-label="Permalink to &quot;Update the scores&quot;">​</a></h2><p><strong>Update Scoring Probabilities</strong> saves your choices, learns again from the won and lost history, and recomputes every open record.</p><ol><li>Click <strong>Update Scoring Probabilities</strong>.</li><li>Read the message and confirm.</li></ol><p>Aureus then shows <strong>Probabilities updated for N open record(s).</strong> Clicking <strong>Save changes</strong> does the same when you changed the details or the date.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Aureus counts, for each sales team, how often each detail appeared on won records and on lost records.</p><ul><li>A <strong>won</strong> record is one in a stage marked as won.</li><li>A <strong>lost</strong> record is one you marked as lost or deleted.</li><li>For each detail on an open record, such as its stage or its country, Aureus checks if that detail is more common on won or on lost records. It combines all the details into one percentage.</li><li>If the team has no history, Aureus uses the history of all teams together.</li><li>The result never goes above 99.99 %. Only a won stage gives 100 %.</li></ul><p><strong>Example:</strong> In the Qualified stage with your Sales team, past records were often won. A valid email also helps. The probability goes up. If similar records were mostly lost, it goes down.</p><h2 id="see-the-reasons" tabindex="-1">See the reasons <a class="header-anchor" href="#see-the-reasons" aria-label="Permalink to &quot;See the reasons&quot;">​</a></h2><p>Open the lead or opportunity and click the information icon next to <strong>Probability</strong>. The window <strong>Probability details</strong> shows:</p><ul><li><strong>Computed probability:</strong> The value Aureus calculated. If there is not enough history, you see <strong>Not enough won and lost history yet to compute a probability.</strong></li><li><strong>Sales team:</strong> The team whose history was used.</li></ul><p>If you typed the probability by hand, the window says so and still shows the computed value.</p><h2 id="automatic-and-manual-probability" tabindex="-1">Automatic and manual probability <a class="header-anchor" href="#automatic-and-manual-probability" aria-label="Permalink to &quot;Automatic and manual probability&quot;">​</a></h2><ul><li>With the field empty, the probability is <strong>Automatic</strong>. Aureus updates it when the record changes.</li><li>If you type your own number, it stays. The details window then adds the note that you set it by hand.</li><li>Click <strong>Use computed probability</strong> to go back to the automatic value.</li><li>Typing the same number as the computed one counts as automatic.</li></ul><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>The stage, sales team, country, state, source, email, phone and probability are watched. Changing one rescores the record.</li><li>Marking a record as lost, deleting it or restoring it triggers a new learning pass.</li><li>Moving an opportunity to a won stage sets its probability to 100 %. Moving it out of that stage makes it automatic again.</li><li>Reports show the probability next to the expected revenue. See <a href="./../reporting/forecast.html">Forecast</a> and <a href="./../reporting/pipeline-analysis.html">Pipeline analysis</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Run <strong>Update Scoring Probabilities</strong> after you close many deals. More history gives better scores.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Scoring needs history. With few won and lost records, the numbers are not reliable.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../acquire-leads/create-lead.html">Create a lead</a></li><li><a href="./../pipeline/manage-opportunities.html">Manage opportunities</a></li><li><a href="./../reporting/pipeline-analysis.html">Pipeline analysis</a></li><li><a href="./">Assign and track</a></li></ul>',24))])}const y=a(l,[["render",d]]);export{b as __pageData,y as default};
